package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class SlaEscalationsBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  String record,calendar="EscalationBrowser"+id();try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","EscalationBrowserAgent","role","agent","password",WorkflowSupport.PASSWORD));record=Service.create(db,"incident",map("short_description","Keep this service commitment","assigned_to","EscalationBrowserAgent"),"admin").get("sys_id").toString();ServiceClocks.calendar(db,actor,map("name",calendar,"calendar",PlatformFoundationTest.calendar()));db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/record/incident/"+record+"/clocks");page.getByLabel("Business calendar",new Page.GetByLabelOptions().setExact(true)).selectOption(calendar);page.getByLabel("Business-minute budget").fill("4");ServiceOutagesBrowserAcceptance.click(page,"Start service clock");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Escalation plan")).press("Enter");assertThat(page.locator("main")).containsText("4 business minutes");page.getByLabel("Warning 1 percentage").fill("50");page.getByLabel("Warning 1 recipient").selectOption("assignee");page.getByLabel("Warning 2 percentage").fill("75");page.getByLabel("Warning 2 recipient").selectOption("responsible");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/sla-warning-plan-light.png")).setFullPage(true));ServiceOutagesBrowserAcceptance.click(page,"Save immutable warning plan");assertThat(page.locator("main")).containsText("50% · assignee");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save immutable warning plan"))).hasCount(0);String clock;try(var db=h.store.open()){clock=db.one("SELECT sla_id FROM os_sla WHERE record_id=?",record).get("sla_id").toString();}SlaEscalationsAcceptance.reset(h.store,clock,SlaEscalationsAcceptance.START);SlaAlertsAcceptance.tick(h.store,SlaEscalationsAcceptance.START+180000);page.reload();assertThat(page.locator("main")).containsText("50% warning processed");assertThat(page.locator("main")).containsText("75% warning processed");assertThat(page.locator("main")).containsText("EscalationBrowserAgent · delivered");ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/sla-warning-outcomes-dark.png")).setFullPage(true));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to service clocks")).press("Enter");assertThat(page.locator("main")).containsText("running");
   try(var staff=browser.newContext()){var inbox=staff.newPage();h.login(inbox,"EscalationBrowserAgent");inbox.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Notifications").setExact(true)).press("Enter");assertThat(inbox.locator("main")).containsText("50% business-time warning");assertThat(inbox.locator("main")).containsText("75% business-time warning");inbox.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review related work")).first().press("Enter");assertThat(inbox.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Service clocks").setExact(true))).isVisible();assertThat(inbox.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Escalation plan"))).hasCount(0);}
  }
 }
}
